+    /// Diagnostic lowering with bounded selected source expressions. Ordinary
+    /// compilation uses its unchanged entry point; all lowering helpers here
+    /// are the same helpers, in the same order. Deferred square expressions
+    /// cannot be represented by a linear combination and are rejected.
+    pub fn compile_inspected(
+        circuit: &Circuit<Scalar>, layout: &InputLayout, selected: &[CircuitIdx],
+    ) -> Result<(Self, Vec<Vec<(u32, Scalar)>>, u32), super::Error> {
+        if selected.len() > 4096 {
+            return Err(Error::InvalidIndex { context: "inspection selection exceeds 4096", index: CircuitIdx::Node(0) }.into());
+        }
+        let mut compiler = Compiler::new(circuit, layout)?;
+        compiler.compile_nodes()?;
+        compiler.compile_assertions()?;
+        compiler.link_inputs()?;
+        let expressions = selected.iter().map(|&index| {
+            if let CircuitIdx::Node(node) = index {
+                if compiler.square_nodes.contains_key(&(node as usize)) {
+                    return Err(Error::InvalidIndex { context: "inspection deferred square", index });
+                }
+            }
+            to_sparse(&compiler.expression(index)?)
+        }).collect::<Result<Vec<_>, Error>>()?;
+        let constant_copy = u32::try_from(compiler.next_column).map_err(|_| Error::SizeOverflow)?;
+        compiler.outline_constant()?;
+        Ok((compiler.finish()?, expressions, constant_copy))
+    }
